CREATE TABLE public.rh2_organization_memberships (
  authority_id text NOT NULL, principal_id text NOT NULL, organization_id text NOT NULL,
  role text NOT NULL, state text NOT NULL CHECK (state IN ('active', 'revoked')),
  created_by_principal_id text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), revoked_at timestamptz,
  revoked_by text, revocation_reason text, version bigint NOT NULL DEFAULT 1 CHECK (version > 0), expires_at timestamptz,
  PRIMARY KEY (authority_id, principal_id, organization_id),
  FOREIGN KEY (authority_id, principal_id, organization_id) REFERENCES public.rh2_authority_principal_organizations(authority_id, principal_id, organization_id),
  FOREIGN KEY (authority_id, organization_id, role) REFERENCES public.rh2_roles(authority_id, organization_id, role),
  CHECK ((state = 'revoked') = (revoked_at IS NOT NULL)),
  CHECK ((revoked_at IS NULL AND revoked_by IS NULL AND revocation_reason IS NULL) OR (revoked_at IS NOT NULL AND revoked_by IS NOT NULL AND length(revocation_reason) >= 1))
);
CREATE INDEX rh2_organization_memberships_org ON public.rh2_organization_memberships (authority_id, organization_id) WHERE state = 'active';

DO $$
DECLARE legacy_table text; differs boolean;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.rh2_data_moves WHERE name = 'work-ontology-cutover:v1' AND completed_at IS NOT NULL) THEN
    IF EXISTS (SELECT 1 FROM public.rh2_authorities) THEN
      RAISE EXCEPTION 'Release the Task cutover and complete its data move before retiring work stores';
    END IF;
    -- A fresh database has no predecessor or data to copy.
    INSERT INTO public.rh2_data_moves (name, completed_at) VALUES ('work-ontology-cutover:v1', clock_timestamp()) ON CONFLICT (name) DO UPDATE SET completed_at = EXCLUDED.completed_at;
  END IF;
  IF EXISTS (SELECT 1 FROM public.rh2_authorities) AND NOT EXISTS (SELECT 1 FROM public.rh2_data_moves WHERE name = 'work-ontology-consumers:v1' AND completed_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Release every Task consumer before retiring its old storage';
  END IF;
  FOREACH legacy_table IN ARRAY ARRAY['rh2_account_grants','rh2_artifacts','rh2_authority_decision_receipts','rh2_authority_grants','rh2_jobs','rh2_memberships','rh2_projects','rh2_room_invitations','rh2_rooms'] LOOP
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE project_id IS NOT NULL AND project_id IS DISTINCT FROM organization_id)', legacy_table) INTO differs;
    IF differs THEN RAISE EXCEPTION 'Project is not an organization identity in %', legacy_table; END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.rh2_authority_grants WHERE resource_project_id IS NOT NULL AND resource_project_id IS DISTINCT FROM COALESCE(resource_organization_id, organization_id)) THEN
    RAISE EXCEPTION 'A grant still names an independent Project';
  END IF;
  IF EXISTS (SELECT 1 FROM public.rh2_authorities WHERE jsonb_array_length(state->'jobs') > 0) THEN
    RAISE EXCEPTION 'An aggregate authority still contains work outside the Task store';
  END IF;
END $$;

