ALTER TABLE public.rh2_room_members ADD COLUMN session_binding jsonb;
ALTER TABLE public.rh2_room_members ADD COLUMN session_conversation_id text;
ALTER TABLE public.rh2_room_members ADD COLUMN bio text;
WITH bindings AS (
 SELECT authority_id, room_id, session_binding->>'agentPrincipalId' AS agent_id,
        min(conversation_id) AS conversation_id
 FROM public.rh2_conversations WHERE session_binding IS NOT NULL
 GROUP BY authority_id, room_id, session_binding->>'agentPrincipalId' HAVING count(*) = 1
)
UPDATE public.rh2_room_members m SET session_binding = c.session_binding, session_conversation_id = c.conversation_id
FROM bindings b JOIN public.rh2_conversations c ON c.authority_id = b.authority_id AND c.conversation_id = b.conversation_id
WHERE m.authority_id = b.authority_id AND m.room_id = b.room_id AND m.principal_id = b.agent_id;

ALTER TABLE public.rh2_room_presets ALTER COLUMN default_conversation_key DROP NOT NULL;
ALTER TABLE public.rh2_room_members ADD COLUMN session_access_conversation_id text;
UPDATE public.rh2_room_members m SET session_access_conversation_id = r.default_conversation_id
FROM public.rh2_rooms r WHERE m.authority_id = r.authority_id AND m.room_id = r.room_id AND m.session_binding IS NOT NULL;
UPDATE public.rh2_conversations c SET name = r.name, updated_at = clock_timestamp(), version = c.version + 1
FROM public.rh2_rooms r WHERE c.authority_id = r.authority_id AND c.conversation_id = r.default_conversation_id
AND c.session_binding IS NULL AND c.name <> r.name;
UPDATE public.rh2_rooms r SET default_conversation_id = NULL, updated_at = clock_timestamp(), version = r.version + 1
WHERE EXISTS (SELECT 1 FROM public.rh2_conversations c WHERE c.authority_id = r.authority_id AND c.conversation_id = r.default_conversation_id AND (c.session_binding IS NOT NULL OR c.closed_at IS NOT NULL));

CREATE TABLE public.rh2_agent_session_turns (
 authority_id text NOT NULL, room_id text NOT NULL, agent_principal_id text NOT NULL,
 turn_id text NOT NULL, sequence bigserial NOT NULL, body text NOT NULL,
 source_conversation_id text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY (authority_id, room_id, agent_principal_id, turn_id),
 FOREIGN KEY (authority_id, room_id, agent_principal_id) REFERENCES public.rh2_room_members(authority_id, room_id, principal_id)
);
CREATE INDEX rh2_agent_session_turns_recent ON public.rh2_agent_session_turns(authority_id, room_id, agent_principal_id, sequence DESC);
CREATE TABLE public.rh2_agent_dm_settings (
 authority_id text NOT NULL, room_id text NOT NULL, agent_principal_id text NOT NULL, principal_id text NOT NULL,
 level text NOT NULL DEFAULT 'all' CHECK (level IN ('all','nothing')), muted boolean NOT NULL DEFAULT false,
 read_sequence bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY (authority_id, room_id, agent_principal_id, principal_id),
 FOREIGN KEY (authority_id, room_id, agent_principal_id) REFERENCES public.rh2_room_members(authority_id, room_id, principal_id),
 FOREIGN KEY (authority_id, room_id, principal_id) REFERENCES public.rh2_room_members(authority_id, room_id, principal_id)
);
